              "zh": "论点、论据与论证是九年级语文阅读与表达中的重要能力。学习它不是给文章贴一个标签，而是要从具体词句、段落关系和写作目的中寻找依据，说明作者怎样组织内容、表达态度。掌握这一知识后，面对议论文阅读相关文本，你能把“我觉得”变成有文本证据的分析，并把答案写成观点明确、依据具体、解释完整的表述。",
