                    "en": "论证方法与作用必须建立在具体语言材料上。先明确概念所指的文本现象，再观察关键词句、上下文关系和表达目的；同一处文字可能承担多种作用，判断时要说明它与人物、情节、主题或读者感受之间的联系。",
