              "en": "交际表达与追问是英语理解和表达中连接形式、意义与语境的一项核心能力。它不仅要求记住规则，还要求判断说话者想突出什么、句子各部分如何配合以及上下文怎样限制词语含义。学习听说策略中的这一内容，可以帮助你读懂真实句子，避免逐词翻译，并在写作和口语中选择准确、自然、符合交际目的的表达。",
              "ja": "交际表达与追问是英语理解和表达中连接形式、意义与语境的一项核心能力。它不仅要求记住规则，还要求判断说话者想突出什么、句子各部分如何配合以及上下文怎样限制词语含义。学习听说策略中的这一内容，可以帮助你读懂真实句子，避免逐词翻译，并在写作和口语中选择准确、自然、符合交际目的的表达。"
