                  "en": "研究内能与热传递时，某用电器两端电压为6 V，通过的电流为0.30 A，通电时间为20 s。求这段时间内的电功，并说明使用的条件。",
                  "ja": "研究内能与热传递时，某用电器两端电压为6 V，通过的电流为0.30 A，通电时间为20 s。求这段时间内的电功，并说明使用的条件。"
